void UCharacterMovementComponent::ProcessLanded(const FHitResult& Hit, float remainingTime, int32 Iterations)
{
	SCOPE_CYCLE_COUNTER(STAT_CharProcessLanded);

	if( CharacterOwner && CharacterOwner->ShouldNotifyLanded(Hit) )
	{
		CharacterOwner->Landed(Hit);
	}
	if( IsFalling() )
	{
		if (GroundMovementMode == MOVE_NavWalking)
		{
			// verify navmesh projection and current floor
			// otherwise movement will be stuck in infinite loop:

		SetPostLandedPhysics(Hit);
	}

	IPathFollowingAgentInterface* PFAgent = GetPathFollowingAgent();
	if (PFAgent)
	{
		PFAgent->OnLanded();
	}

	StartNewPhysics(remainingTime, Iterations);
}

fn c516_delta(probe:Res<C458Probe>,control:Res<C516Control>,mut time:ResMut<TimeUpdateStrategy>) {
    if probe.frame==control.frame {
        *time=TimeUpdateStrategy::ManualDuration(Duration::from_secs_f32(0.06));
    } else if probe.frame==control.frame+1 {
        *time=TimeUpdateStrategy::ManualDuration(Duration::from_secs_f32(1.0/30.0));
    }
}

fn c571_clock(probe: Res<C458Probe>, mut clock: ResMut<TimeUpdateStrategy>) {
    if (41..=75).contains(&probe.frame) {
        *clock = TimeUpdateStrategy::ManualDuration(Duration::from_micros(31_250));
    }
}
